UPDATE projects SET tagline = 'A modern web app for FDJ lottery players — Loto, EuroMillions and Crescendo. lotoKarma lets you generate number grids, check them against the complete draw history, browse the archives, and analyze frequency statistics to refine your choices.' WHERE id = 10;
UPDATE projects SET tagline = 'Cartomancy: shuffle, cut, draw — just like with a real deck.' WHERE id = 17;

ON DUPLICATE KEY UPDATE category = VALUES(category), tagline = VALUES(tagline);
