INSERT INTO project_translations (project_id, lang, category, tagline) VALUES
  (1, 'fr', 'Outils développeur et accessibilité', 'Une inspection du DOM en direct qui transforme les problèmes RGAA et WCAG en correctifs que votre équipe peut vraiment livrer.'),
  (1, 'de', 'Entwickler- und Barrierefreiheits-Tools', 'Live-DOM-Inspektion, die RGAA- und WCAG-Probleme in Korrekturen verwandelt, die Ihr Team tatsächlich ausliefern kann.'),
  (1, 'ko', '개발자 및 접근성 도구', 'RGAA와 WCAG 문제를 팀이 실제로 배포할 수 있는 수정안으로 바꿔주는 실시간 DOM 검사 도구.'),
  (1, 'ja', '開発者・アクセシビリティツール', 'RGAAとWCAGの問題を、チームが実際に出荷できる修正に変える、ライブDOM検査ツール。'),
  (1, 'es', 'Herramientas de desarrollo y accesibilidad', 'Inspección del DOM en vivo que convierte los problemas de RGAA y WCAG en correcciones que tu equipo puede implementar de verdad.'),
  (2, 'fr', 'Finance', 'Un tableau de bord unique pour tous les comptes — PEA, PER, CTO — avec les indicateurs qui comptent.'),
  (2, 'de', 'Finanzen', 'Ein Dashboard für jedes Konto — PEA, PER, CTO — mit den KPIs, auf die es ankommt.'),
  (2, 'ko', '금융', 'PEA, PER, CTO 등 모든 계좌를 위한 하나의 대시보드 — 중요한 핵심 지표(KPI)와 함께.'),
  (2, 'ja', 'ファイナンス', 'PEA、PER、CTOなど、あらゆる口座を一つのダッシュボードで — 本当に重要なKPIとともに。'),
  (2, 'es', 'Finanzas', 'Un panel único para cada cuenta — PEA, PER, CTO — con los KPI que importan.'),
  (3, 'fr', 'Créatif', 'Choisissez une image, sélectionnez un style, regardez-la se transformer.'),
  (3, 'de', 'Kreativ', 'Bild auswählen, Stil wählen, die Verwandlung beobachten.'),
  (3, 'ko', '크리에이티브', '이미지를 고르고, 스타일을 선택하고, 변신하는 모습을 지켜보세요.'),
  (3, 'ja', 'クリエイティブ', '画像を選び、スタイルを選ぶだけで、変身する様子を見届けよう。'),
  (3, 'es', 'Creativo', 'Elige una imagen, elige un estilo, mira cómo se transforma.'),
  (4, 'fr', 'Outils développeur', 'Des conseils d\'accessibilité directement dans l\'éditeur — templates Angular, ARIA, ordre de tabulation.'),
  (4, 'de', 'Entwickler-Tools', 'Barrierefreiheits-Hinweise direkt im Editor — Angular-Templates, ARIA, Fokusreihenfolge.'),
  (4, 'ko', '개발자 도구', '에디터 안에서 바로 확인하는 접근성 가이드 — Angular 템플릿, ARIA, 포커스 순서.'),
  (4, 'ja', '開発者ツール', 'エディタ内でアクセシビリティを確認 — Angularテンプレート、ARIA、フォーカス順。'),
  (4, 'es', 'Herramientas para desarrolladores', 'Orientación de accesibilidad directamente en el editor — plantillas Angular, ARIA, orden de foco.'),
  (5, 'fr', 'Outils développeur', 'Axe-core et Playwright intégrés aux pull requests, pour qu\'aucune régression ne passe.'),
